"""Pre-implementation parameter investigation on calibration cases ONLY."""
from explore import *
from tools.puzzle_production.contract import digest

def evaluate(p, variant='chosen', scale=F(1)):
    d,s,w=p['demand'],p['search'],p['workload']
    waves=list(zip(d['trajectory'],s['trajectory']))
    high=d['highest_family']
    fluid=high in ('E0','E1') and all(F(*q['offer'])>=F(1,2) or F(*q['gain'])>=F(1,2)
        for a,q in waves if a['family']=='E1')
    context=F(0)
    for a,q in waves:
        if a['family'] not in ('E2','E3'): continue
        b=F(a['interacting_blocks'],1)/(F(*q['offer'])*q['state']['open_lines'])
        ambiguity=F(q['state']['ambiguous_required_cells'],q['state']['ambiguous_required_cells']+q['state']['unique_owner_required_cells']+1)
        context=max(context,max(0,b-1)/(b+3),ambiguity)
    demand=F(0) if high=='E0' else F(1,4) if fluid else F(int(high[1])) + context/4
    run=longest=count=0; strains=[]
    for a,q in waves:
        if a['family']!='E0': strains.append(F(*q['strain']))
        narrow=a['family']!='E0' and q['bottleneck']
        run=run+1 if narrow else 0;longest=max(longest,run);count+=narrow
    peak=max(strains,default=F(0))
    search=peak+F(min(count,4)+min(longest,4),32)
    work=min(F(1,4), max(F(0),F(w['fill_spans']+w['empty_spans']-40,640)))
    if variant=='no_context': demand-=context/4
    if variant=='no_search': search=F(0)
    if variant=='mean_search': search=(sum(strains)/len(strains) if strains else F(0))
    if variant=='diluted_strong' and high in ('E2','E3'):
        demand=1+(demand-1)*F(*d['strong_information_fraction'])
    if variant=='no_work':work=F(0)
    if variant=='raw_area': work=F(w['structure']['cells'],400)
    if variant=='no_repeat':search=peak
    if variant=='sensitivity':search*=scale
    level=lambda n:1+sum(n>=i for i in (1,2,3,4))
    base=demand+search
    if variant!='raw_area':
        ceiling=max(level(base), 3 if high in ('E0','E1') or search<F(3,4) else 4 if high=='E2' else 5)
        if fluid: work=F(0)
        elif ceiling<5: work=min(work,(ceiling-base)/2)
    return dict(demand=demand,search=search,work=work,score=base+work,level=level(base+work),peak=peak,count=count,longest=longest,context=context)

if __name__=='__main__':
    refs=json.loads((Path(__file__).resolve().parents[2]/'tools/puzzle_production/sd2_references_0_4.json').read_text(encoding='utf-8'))
    variants=['chosen','no_context','no_search','mean_search','diluted_strong','no_work','raw_area','no_repeat','minus10','plus10']
    out=[]
    for c in refs['cases']:
        if c['split']!='calibration':continue
        p=validate_logic(c['logic']);t=analyze(p);pr=profiles(p,t)
        results={}
        for v in variants:
            if c['pattern']=='pair':r=dict(score=F(9,2),level=5,demand=F(9,2),search=F(0),work=F(0))
            else:r=evaluate(pr,'sensitivity' if v in ('minus10','plus10') else v,F(9,10) if v=='minus10' else F(11,10))
            results[v]={k:([x.numerator,x.denominator] if isinstance(x,F) else x) for k,x in r.items()}
        out.append(dict(id=c['id'],expected=c['expected_level'],results=results))
        print(c['id'],c['expected_level'], [(v,results[v]['level']) for v in variants], 'chosen',float(F(*results['chosen']['score'])),flush=True)
    result=dict(format='picross-sd2-comparison-v1',reference_hash=digest(refs),split='calibration',candidates=variants,cases=out)
    (Path(__file__).parent/'comparison.json').write_text(json.dumps(result,indent=2,sort_keys=True)+'\n')
    print('match counts',{v:sum(c['results'][v]['level']==c['expected'] for c in out) for v in variants})
